import org.apache.commons.lang3.LocaleUtils;
import java.util.Locale;
import java.util.List;

public class Probe {
    public static void main(String[] args) {
        System.out.println("US lookup: " + LocaleUtils.localeLookupList(Locale.US));
        System.out.println("fr_CA_xxx lookup: " + LocaleUtils.localeLookupList(new Locale("fr","CA","xxx")));
        System.out.println("fr lookup with default en: " + LocaleUtils.localeLookupList(new Locale("fr"), Locale.ENGLISH));
        System.out.println("null,null lookup: " + LocaleUtils.localeLookupList(null, null));
        System.out.println("toLocale en_001: " + LocaleUtils.toLocale("en_001"));
        System.out.println("toLocale US: " + LocaleUtils.toLocale("US").getLanguage() + "|" + LocaleUtils.toLocale("US").getCountry());
        try { LocaleUtils.toLocale("a"); System.out.println("no throw a"); } catch (IllegalArgumentException e) { System.out.println("threw for 'a': " + e.getMessage()); }
        try { LocaleUtils.toLocale("_G"); } catch (IllegalArgumentException e) { System.out.println("threw for '_G': " + e.getMessage()); }
        System.out.println("toLocale _GB: " + LocaleUtils.toLocale("_GB"));
        try { LocaleUtils.toLocale("_gb"); } catch (IllegalArgumentException e) { System.out.println("threw for '_gb': " + e.getMessage()); }
        try { LocaleUtils.toLocale("_GBx"); } catch (IllegalArgumentException e) { System.out.println("threw for '_GBx': " + e.getMessage()); }
        System.out.println("toLocale _GB_xxx: " + LocaleUtils.toLocale("_GB_xxx"));
        try { LocaleUtils.toLocale("_GBXxxx"); } catch (IllegalArgumentException e) { System.out.println("threw for '_GBXxxx': " + e.getMessage()); }
        System.out.println("toLocale th_TH_TH_#u-nu-thai: " + LocaleUtils.toLocale("th_TH_TH_#u-nu-thai"));
        try { LocaleUtils.toLocale("en_gb"); } catch (IllegalArgumentException e) { System.out.println("threw for 'en_gb': " + e.getMessage()); }
        System.out.println("toLocale en-GB: " + LocaleUtils.toLocale("en-GB"));
        System.out.println("toLocale \"\": [" + LocaleUtils.toLocale("") + "]");
        System.out.println("toLocale null: " + LocaleUtils.toLocale((String) null));
        List<Locale> cByL = LocaleUtils.countriesByLanguage("en");
        System.out.println("countriesByLanguage en size: " + cByL.size());
        System.out.println("sample: " + cByL.subList(0, Math.min(5, cByL.size())));
        List<Locale> lByC = LocaleUtils.languagesByCountry("GB");
        System.out.println("languagesByCountry GB: " + lByC);
        System.out.println("countriesByLanguage null: " + LocaleUtils.countriesByLanguage(null));
        System.out.println("languagesByCountry null: " + LocaleUtils.languagesByCountry(null));
        System.out.println("isAvailableLocale US: " + LocaleUtils.isAvailableLocale(Locale.US));
        System.out.println("isAvailableLocale weird: " + LocaleUtils.isAvailableLocale(new Locale("xx","YY")));
        System.out.println("isLanguageUndetermined null: " + LocaleUtils.isLanguageUndetermined(null));
        System.out.println("isLanguageUndetermined en: " + LocaleUtils.isLanguageUndetermined(Locale.ENGLISH));
        System.out.println("isLanguageUndetermined weird: " + LocaleUtils.isLanguageUndetermined(new Locale("a")));
        try {
            LocaleUtils.availableLocaleList().add(Locale.US);
            System.out.println("list mutable!");
        } catch (UnsupportedOperationException e) { System.out.println("list immutable"); }
    }
}
